<script setup lang="ts">
import { Head, useForm } from '@inertiajs/vue3'
const props=defineProps<{latest:any;history:any[];thresholds:Record<string,number>}>()
const form=useForm({cpu_percent:Number(props.thresholds.cpu_percent||85),ram_percent:Number(props.thresholds.ram_percent||85),disk_percent:Number(props.thresholds.disk_percent||90)})
const percent=(a:number,b:number)=>b?Math.min(100,a/b*100):0
</script>
<template><Head title="مانیتورینگ سرور"/><v-container fluid class="pa-6"><h1 class="text-h4 mb-5">مانیتورینگ زنده</h1><v-row><v-col v-for="item in [{name:'CPU',value:latest?.cpu_percent||0},{name:'RAM',value:percent(latest?.ram_used_bytes||0,latest?.ram_total_bytes||0)},{name:'Disk',value:percent(latest?.disk_used_bytes||0,latest?.disk_total_bytes||0)}]" :key="item.name" cols="12" md="4"><v-card rounded="xl" class="pa-5 text-center"><v-progress-circular :model-value="item.value" :size="130" :width="12" color="primary">{{ item.value.toFixed(1) }}%</v-progress-circular><div class="text-h6 mt-3">{{ item.name }}</div></v-card></v-col></v-row><v-row class="mt-2"><v-col cols="6" md="3"><v-card rounded="xl" class="pa-4"><div>کاربران</div><div class="text-h4">{{ latest?.users_total??'—' }}</div></v-card></v-col><v-col cols="6" md="3"><v-card rounded="xl" class="pa-4"><div>اتاق‌ها</div><div class="text-h4">{{ latest?.rooms_total??'—' }}</div></v-card></v-col><v-col cols="6" md="3"><v-card rounded="xl" class="pa-4"><div>آنلاین</div><div class="text-h4">{{ latest?.online_users??'—' }}</div></v-card></v-col><v-col cols="6" md="3"><v-card rounded="xl" class="pa-4"><div>دیتابیس</div><div class="text-h6">{{ latest?.database_bytes??'—' }} B</div></v-card></v-col></v-row><v-card rounded="xl" class="pa-5 mt-5"><v-card-title>آستانه هشدار منابع</v-card-title><v-form @submit.prevent="form.put('/metrics/thresholds')"><v-row><v-col cols="4"><v-text-field v-model.number="form.cpu_percent" label="CPU %" type="number"/></v-col><v-col cols="4"><v-text-field v-model.number="form.ram_percent" label="RAM %" type="number"/></v-col><v-col cols="4"><v-text-field v-model.number="form.disk_percent" label="Disk %" type="number"/></v-col></v-row><v-btn type="submit" color="primary">ذخیره</v-btn></v-form></v-card></v-container></template>
